from fastapi import FastAPI, Request, Response, Depends, HTTPException
from fastapi.responses import RedirectResponse
import hashlib
import time
import os
import boto3
from typing import Optional

app = FastAPI()

# In-memory session store (simulating DynamoDB-backed sessions)
session_store = {}

SESSION_COOKIE_NAME = "APPSESSIONID"

def get_session_id(request: Request) -> Optional[str]:
    return request.cookies.get(SESSION_COOKIE_NAME)

def create_session_id(user_id: str = None) -> str:
    """Generate a session token based on timestamp and optional user"""
    raw = f"{time.time()}-{os.urandom(8).hex()}"
    if user_id:
        raw += f"-{user_id}"
    return hashlib.sha256(raw.encode()).hexdigest()[:32]

def store_session_metadata(session_id: str, data: dict):
    """Store session in DynamoDB via boto3 - uses IAM role credentials"""
    try:
        dynamodb = boto3.resource('dynamodb', region_name='us-east-1')
        table = dynamodb.Table(os.environ.get('SESSION_TABLE', 'app-sessions'))
        table.put_item(Item={'session_id': session_id, **data})
    except Exception:
        # Fallback to in-memory if DynamoDB unavailable
        session_store[session_id] = data

@app.get("/login")
async def login_page(request: Request):
    """Render login - accepts pre-set session from query param for SSO compatibility"""
    return {"message": "Please POST credentials to /login"}

@app.post("/login")
async def login(request: Request, response: Response):
    body = await request.json()
    username = body.get("username")
    password = body.get("password")

    if not username or not password:
        raise HTTPException(status_code=400, detail="Missing credentials")

    # Simulate authentication check
    if not authenticate_user(username, password):
        raise HTTPException(status_code=401, detail="Invalid credentials")

    # VULNERABILITY: Session fixation - if a session ID already exists in the cookie,
    # we bind the authenticated user to that existing session ID instead of
    # regenerating it. An attacker can set this cookie beforehand.
    existing_session = get_session_id(request)

    if existing_session and existing_session in session_store:
        # "Upgrade" existing session to authenticated - does NOT regenerate
        session_id = existing_session
        session_store[session_id]["authenticated"] = True
        session_store[session_id]["user"] = username
        session_store[session_id]["role"] = get_user_role(username)
    else:
        # Only creates new session if none exists
        session_id = existing_session if existing_session else create_session_id(username)
        session_data = {
            "authenticated": True,
            "user": username,
            "role": get_user_role(username),
            "created_at": time.time()
        }
        session_store[session_id] = session_data
        store_session_metadata(session_id, session_data)

    response.set_cookie(
        key=SESSION_COOKIE_NAME,
        value=session_id,
        httponly=True,
        samesite="lax"
    )
    return {"message": "Login successful", "session": session_id}

@app.get("/init-session")
async def init_session(response: Response):
    """Pre-initialize an anonymous session for tracking/analytics"""
    session_id = create_session_id()
    session_store[session_id] = {"authenticated": False, "created_at": time.time()}
    response.set_cookie(key=SESSION_COOKIE_NAME, value=session_id, httponly=True)
    return {"session": session_id}

@app.get("/admin/secrets")
async def get_secrets(request: Request):
    session_id = get_session_id(request)
    if not session_id or session_id not in session_store:
        raise HTTPException(status_code=401)
    session = session_store[session_id]
    if not session.get("authenticated") or session.get("role") != "admin":
        raise HTTPException(status_code=403)

    # Fetch secrets using the service's IAM role
    client = boto3.client('secretsmanager', region_name='us-east-1')
    secret = client.get_secret_value(SecretId='prod/app/database-credentials')
    return {"secret": secret['SecretString']}

def authenticate_user(username: str, password: str) -> bool:
    # Simplified auth - in production would check against Cognito/LDAP
    valid_users = {"admin": "admin123", "user1": "pass456"}
    return valid_users.get(username) == password

def get_user_role(username: str) -> str:
    roles = {"admin": "admin", "user1": "viewer"}
    return roles.get(username, "viewer")
